+package com.example.contact;
+
+import java.util.List;
+import java.util.concurrent.CopyOnWriteArrayList;
+
+import org.springframework.stereotype.Service;
+
+/**
+ * Keeps the sent messages in memory for the lifetime of the application.
+ */
+@Service
+public class MessageService {
+
+    private final CopyOnWriteArrayList<ContactMessage> messages = new CopyOnWriteArrayList<>();
+
+    public void send(ContactMessage message) {
+        messages.addFirst(message);
+    }
+
+    /** All sent messages, newest first. */
+    public List<ContactMessage> findAll() {
+        return List.copyOf(messages);
+    }
+}
